// ChannelNotFoundError 요청된 채널이 존재하지 않는 경우
//
// ChannelNotFoundError is a variant of [GetPgCardPromotionsError], [IssueBillingKeyError], [IssueCashReceiptError], [PayInstantlyError], [PayWithBillingKeyError], [SendIdentityVerificationError], identified by type "CHANNEL_NOT_FOUND".
type ChannelNotFoundError struct {
	Message *string `json:"message,omitempty"`
}

func (ChannelNotFoundError) isGetPgCardPromotionsError() {}

func (ChannelNotFoundError) isIssueBillingKeyError() {}

func (ChannelNotFoundError) isIssueCashReceiptError() {}

func (ChannelNotFoundError) isPayInstantlyError() {}

func (ChannelNotFoundError) isPayWithBillingKeyError() {}

func (ChannelNotFoundError) isSendIdentityVerificationError() {}

// MarshalJSON writes the "type" discriminator along with the fields.
func (v ChannelNotFoundError) MarshalJSON() ([]byte, error) {
	type alias ChannelNotFoundError
	return json.Marshal(struct {
		Discriminator string `json:"type"`
		alias
	}{"CHANNEL_NOT_FOUND", alias(v)})
}

func (e *ChannelNotFoundError) Error() string { return errorString("CHANNEL_NOT_FOUND", e.Message) }

